/**
 * ============================================================================
 * 視覺藝術作品署名與靈感宣告 (ATTRIBUTION & INSPIRATION DECLARATION)
 * ============================================================================
 * 作者 (Author / Code Adaptor): Uncler M
 * 靈感啟發來源 (Inspired By): aorbital - "Processing x 量子自旋系統《Kuramoto Synchronization》"
 * 原始作品討論 (Original Note): http://xhslink.com/o/8CpGBYtMUFO
 * 授權協議 (License): Creative Commons Attribution-NonCommercial-ShareAlike 4.0 (CC BY-NC-SA 4.0)
 * 
 * [說明 / Notice]
 * 本作品由 Uncler M 編寫與視聽化對應。幾何演算法靈感取材自 Kuramoto Yoshiki
 * 之藏本非線形耦合振盪子同步模型（Kuramoto Synchronization）與 Jared Tarbell 幾何粒子視覺。
 * 專為 4K MV Visual Integration Editor 專案打造。
 * ============================================================================
 */

let NUM_NODES = 240;
let nodes = [];
let rotX = 0, rotY = 0;

let smoothedSubBass = 0.0;
let smoothedPercussive = 0.0;
let smoothedMid = 0.0;

setup = () => {
  p5.disableFriendlyErrors = true;
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1.0);
  ellipseMode(CENTER);

  // 初始化 Kuramoto 藏本振盪子陣列
  let radius = min(width, height) * 0.35;
  for (let i = 0; i < NUM_NODES; i++) {
    let u = random(1.0);
    let v = random(1.0);
    let theta = u * TWO_PI;
    let phi = acos(2 * v - 1);

    nodes.push({
      // 3D Bloch 球面坐標
      bx: radius * sin(phi) * cos(theta),
      by: radius * sin(phi) * sin(theta),
      bz: radius * cos(phi),
      // 藏本同步相角與固有頻率
      phase: random(TWO_PI),
      naturalFreq: random(0.01, 0.05),
      radius: radius
    });
  }
};

draw = () => {
  // 1. 動態音訊信號平滑處理
  let rawSubBass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof sub_bass_ratio !== 'undefined' ? sub_bass_ratio : (mouseIsPressed ? 0.8 : 0.2));
  let rawPercussive = (typeof percussive !== 'undefined') ? percussive : (mouseIsPressed ? 0.9 : 0.1);
  let rawMid = (typeof mid !== 'undefined') ? mid : (typeof mid_ratio !== 'undefined' ? mid_ratio : 0.3);

  smoothedSubBass += (rawSubBass - smoothedSubBass) * 0.15;
  smoothedPercussive += (rawPercussive - smoothedPercussive) * 0.3;
  smoothedMid += (rawMid - smoothedMid) * 0.2;

  // 2. 尾蹟半透明背景沖刷
  background(240, 30, 6, 0.2);

  // 3. 全局 3D 視角旋轉
  rotX += 0.003 + smoothedMid * 0.01;
  rotY += 0.005 + smoothedSubBass * 0.015;

  let cx = width * 0.5;
  let cy = height * 0.5;

  // Kuramoto 耦合強度 K (低頻動態驅動：K 越高，粒子自發同步越強)
  let couplingK = 0.05 + smoothedSubBass * 0.45;
  let currentHue = (typeof chord_hue !== 'undefined' && chord_hue > 0) ? chord_hue : 280;

  // 4. 重拍觸發「相位衝擊波 (Phase Shockwave)」
  if (smoothedPercussive > 0.65 && random() < 0.15) {
    for (let i = 0; i < NUM_NODES; i++) {
      if (random() < 0.4) {
        nodes[i].phase += random(-PI, PI);
      }
    }
  }

  // 5. Kuramoto 微分方程迭代更新 (Phase Dynamics)
  for (let i = 0; i < NUM_NODES; i++) {
    let n1 = nodes[i];
    let sumSine = 0;

    for (let j = 0; j < NUM_NODES; j++) {
      if (i !== j) {
        sumSine += sin(nodes[j].phase - n1.phase);
      }
    }

    // dTheta/dt = omega + (K/N) * sum(sin(theta_j - theta_i))
    let dPhase = n1.naturalFreq + (couplingK / NUM_NODES) * sumSine;
    n1.phase = (n1.phase + dPhase) % TWO_PI;
  }

  // 6. 3D Bloch 球面投影與自旋鏈渲染
  let projected = [];

  for (let i = 0; i < NUM_NODES; i++) {
    let n = nodes[i];

    // 3D 矩陣旋轉
    let x1 = n.bx * cos(rotY) + n.bz * sin(rotY);
    let z1 = -n.bx * sin(rotY) + n.bz * cos(rotY);

    let y2 = n.by * cos(rotX) - z1 * sin(rotX);
    let z2 = n.by * sin(rotX) + z1 * cos(rotX);

    // 相位振盪引發的 Bloch 球面呼吸動態
    let rOffset = sin(n.phase) * (20 + smoothedSubBass * 60);
    let scaleFactor = 400 / (400 + z2 + 100);

    let px = cx + x1 * (1.0 + rOffset * 0.003) * scaleFactor;
    let py = cy + y2 * (1.0 + rOffset * 0.003) * scaleFactor;

    projected.push({ px: px, py: py, z: z2, phase: n.phase, scale: scaleFactor });
  }

  // 排序（由遠至近渲染，確保深度感）
  projected.sort((a, b) => a.z - b.z);

  // 7. 渲染自旋粒子與相干能量連線 (Phase Coherence Lines)
  for (let i = 0; i < projected.length; i++) {
    let p1 = projected[i];

    // 與鄰近相位相近的點進行能量發光連線
    for (let j = i + 1; j < projected.length; j += 2) {
      let p2 = projected[j];
      let phaseDiff = abs(sin(p1.phase - p2.phase));
      let distPx = dist(p1.px, p1.py, p2.px, p2.py);

      if (distPx < 120 * p1.scale && phaseDiff < 0.3) {
        let alpha = map(phaseDiff, 0, 0.3, 0.6, 0.0) * (0.3 + smoothedSubBass * 0.7);
        stroke((currentHue + p1.phase * 30) % 360, 80, 95, alpha);
        strokeWeight(0.8 * p1.scale + smoothedPercussive * 2.0);
        line(p1.px, p1.py, p2.px, p2.py);
      }
    }

    // 繪製量子自旋節點 (Quantum Node)
    let nodeHue = (currentHue + (p1.phase / TWO_PI) * 360) % 360;
    let nodeSize = (4 + sin(p1.phase) * 3 + smoothedSubBass * 8) * p1.scale;

    fill(nodeHue, 85, 100, 0.85);
    noStroke();
    ellipse(p1.px, p1.py, nodeSize, nodeSize);
  }
};

// === 運行時防崩潰護欄與 DOM 代理 Stubs ===
